from itertools import combinations
import random

def find_cycles_of_length_k(edges, n, k):
    """Find all cycles of length k in the graph."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    cycles = []

    def dfs(start, current, path, visited):
        if len(path) == k:
            if start in adj[current]:
                cycles.append(tuple(sorted(path)))
            return

        for neighbor in adj[current]:
            if neighbor == start and len(path) < k - 1:
                continue
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                dfs(start, neighbor, path, visited)
                path.pop()
                visited.remove(neighbor)

    for start in range(n):
        visited = {start}
        dfs(start, start, [start], visited)

    # Remove duplicates
    unique_cycles = set()
    for cycle in cycles:
        unique_cycles.add(cycle)

    return list(unique_cycles)

def has_short_cycle(edges, n):
    """Check if graph has any cycle of length 3, 4, 5, or 6."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for cycles of length 3, 4, 5, 6
    for k in [3, 4, 5, 6]:
        if find_cycles_of_length_k(edges, n, k):
            return True
    return False

