from collections import deque

def has_short_cycle_fast(adj, n, new_u, new_v):
    """Check if adding edge (new_u, new_v) creates a cycle of length 3-6."""
    # BFS from new_u to new_v, avoiding the direct edge
    # If distance is 2, 3, 4, or 5, we have a cycle of length 3, 4, 5, or 6

    # Check for cycle of length 3: common neighbor
    for w in adj[new_u]:
        if w in adj[new_v]:
            return True

    # BFS to find shortest path from new_u to new_v (not using the new edge)
    visited = {new_u}
    queue = deque([(new_u, 0)])

    while queue:
        node, dist = queue.popleft()
        if dist >= 5:  # We only care about paths of length 2-5
            break
        for neighbor in adj[node]:
            if neighbor == new_v:
                # Found path of length dist+1, so cycle of length dist+2
                cycle_len = dist + 2
                if cycle_len <= 6:
                    return True
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    return False

def build_graph_greedy(n, coloring, max_edges, seed=None):
    """Build a graph with given coloring, avoiding short cycles."""
    if seed is not None:
        random.seed(seed)

    adj = {i: set() for i in range(n)}
    edges = []

    # Generate all possible edges
    possible_edges = []
    for u in range(n):
        for v in range(u+1, n):
            if coloring[u] != coloring[v]:
                possible_edges.append((u, v))

    random.shuffle(possible_edges)

    for u, v in possible_edges:
        if len(edges) >= max_edges:
            break
        if not has_short_cycle_fast(adj, n, u, v):
            edges.append((u, v))
            adj[u].add(v)
            adj[v].add(u)

    return edges

