import random
from collections import defaultdict

n = 19
target = 29

def get_adj(edges, n):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj

def count_short_cycles(edges, n):
    """Count cycles of length 3-6."""
    adj = get_adj(edges, n)
    count = 0

    # Check for each possible cycle length
    for k in [3, 4, 5, 6]:
        # For each starting vertex
        for start in range(n):
            # BFS/DFS to find cycles of length k
            # path = [start, ...]
            stack = [(start, [start], {start})]
            while stack:
                node, path, visited = stack.pop()
                if len(path) == k:
                    if start in adj[node]:
                        count += 1
                    continue
                for neighbor in adj[node]:
                    if neighbor == start and len(path) == k - 1:
                        count += 1
                    elif neighbor not in visited and len(path) < k - 1:
                        stack.append((neighbor, path + [neighbor], visited | {neighbor}))

    return count // (2 * 6)  # Each cycle counted multiple times

def is_3_colorable(edges, n):
    """Check if graph is 3-colorable using backtracking."""
    adj = get_adj(edges, n)
    color = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and color[neighbor] == c:
                    valid = False
                    break
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                color[v] = -1
        return False

    return backtrack(0)

