            if coloring[c] == coloring[a] or coloring[c] == coloring[b]:
                continue
            e_ab = edge_vars.get((min(a,b), max(a,b)))
            e_bc = edge_vars.get((min(b,c), max(b,c)))
            e_ac = edge_vars.get((min(a,c), max(a,c)))
            if e_ab and e_bc and e_ac:
                clauses.append([-e_ab, -e_bc, -e_ac])

