        min_idx = cycle.index(min(cycle))
        normalized = tuple(cycle[min_idx:] + cycle[:min_idx])
        rev = tuple([normalized[0]] + list(reversed(normalized[1:])))
        if rev < normalized:
            normalized = rev
        if normalized in seen_cycles:
            continue
        seen_cycles.add(normalized)

        edge_list = []
        for i in range(4):
            u, w = normalized[i], normalized[(i+1)%4]
            if u > w:
